      <div style={{ display: 'flex', flexDirection: 'column', fontSize: 16 }}>
        <div style={{ wordSpacing: 10 }}>Hello world and more</div>
        <div style={{ wordSpacing: -3 }}>Hello world and more</div>
        {/* Inherited, and relative to the font size. */}
