/**
 * Renders a web page with Satori as an SVG, like a screenshot of its
 * viewport, e.g. `/api/screenshot?url=https://nextjs.org&width=1280`.
 *
 * Only available in development: the page is fetched from the server, with
 * its stylesheets and fonts. The `Server-Timing` header reports the time of
 * each step, and `X-Screenshot` what was loaded, as URI-encoded JSON.
 */

import type { NextApiRequest, NextApiResponse } from 'next'
import { screenshot } from '../../utils/screenshot'

const MAX_STYLE_ERRORS = 50

export const config = {
  // The SVGs of long pages are often larger than 4MB.
  api: { responseLimit: false },
}

const first = (value: string | string[] | undefined) =>
  Array.isArray(value) ? value[0] : value

function size(value: string | undefined, fallback: number, max: number) {
  const number = Math.round(Number(value))
  return Number.isFinite(number) && number > 0
    ? Math.min(number, max)
    : fallback
}

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (process.env.NODE_ENV !== 'development') {
    res.status(404).end()
    return
  }

  let url: URL
  try {
    url = new URL(first(req.query.url) ?? '')
    if (url.protocol !== 'http:' && url.protocol !== 'https:') throw new Error()
  } catch {
    res.status(400).json({ error: 'Pass an http(s) URL as `url`.' })
    return
  }
  const width = size(first(req.query.width), 1280, 4000)
  const height = size(first(req.query.height), 800, 8000)

  try {
    const result = await screenshot(url, { width, height })
    res.setHeader('Content-Type', 'image/svg+xml')
    res.setHeader('Cache-Control', 'no-store')
    res.setHeader(
      'Server-Timing',
      Object.entries(result.timings)
        .map(([name, duration]) => `${name};dur=${duration.toFixed(1)}`)
        .join(', ')
    )
    res.setHeader(
      'X-Screenshot',
      encodeURIComponent(
        JSON.stringify({
          stylesheets: result.stylesheets,
          fonts: result.fonts,
          styleErrors: result.styleErrors.slice(0, MAX_STYLE_ERRORS),
          styleErrorCount: result.styleErrors.length,
        })
      )
    )
    res.send(result.svg)
  } catch (error) {
    res.status(500).json({
      error: error instanceof Error ? error.message : String(error),
    })
  }
}

/**
 * Renders a 1200×630 PNG card with a WebGL shader background and the `text`
 * query parameter on top, e.g. `/api/shader-card?text=Hello`.
 *
 * WebGL runs on the CPU through headless-gl (ANGLE + SwiftShader). The
 * `Server-Timing` header reports the time spent in each step.
 */

/* eslint-disable react/no-unknown-property -- `webgl` is a Satori prop. */
import type { NextApiRequest, NextApiResponse } from 'next'
import { existsSync, readFileSync } from 'node:fs'
import { readFile } from 'node:fs/promises'
import { createRequire } from 'node:module'
import path from 'node:path'
import { Resvg } from '@resvg/resvg-js'
import satori from 'satori/experimental'

// The playground declares Satori as an untyped module, so mirror its type.
type WebGLCanvasRenderer = (
  gl: WebGL2RenderingContext,
  info: { width: number; height: number }
) => void

declare module 'react' {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  interface CanvasHTMLAttributes<T> {
    webgl?: WebGLCanvasRenderer
  }
}

const WIDTH = 1200
const HEIGHT = 630
const MAX_TEXT_LENGTH = 200

const VERTEX_SHADER = `#version 300 es
in vec2 position;
void main() {
  gl_Position = vec4(position, 0.0, 1.0);
}`

// Domain-warped fractal noise.
const FRAGMENT_SHADER = `#version 300 es
precision highp float;
uniform vec2 resolution;
uniform float seed;
out vec4 fragColor;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
    u.y
  );
}

float fbm(vec2 p) {
  float value = 0.0;
  float amplitude = 0.5;
  for (int i = 0; i < 5; i++) {
    value += amplitude * noise(p);
    p *= 2.0;
    amplitude *= 0.5;
  }
  return value;
}

void main() {
  vec2 uv = gl_FragCoord.xy / resolution.y + seed;
  vec2 q = vec2(fbm(uv * 3.0), fbm(uv * 3.0 + 5.2));
  float n = fbm(uv * 3.0 + 4.0 * q);
  vec3 color = mix(vec3(0.05, 0.02, 0.15), vec3(0.9, 0.4, 0.2), n);
  color = mix(color, vec3(0.2, 0.7, 1.0), q.x * q.y);
  fragColor = vec4(color, 1.0);
}`

// glibc dlopen flags. RTLD_NODELETE keeps a library loaded after Node closes
// its handle.
const RTLD_NOW = 0x2
const RTLD_GLOBAL = 0x100
const RTLD_NODELETE = 0x1000

type ProcessWithDlopen = NodeJS.Process & {
  dlopen(module: object, filename: string, flags: number): void
}

const LIBS_DIRECTORY = path.join(process.cwd(), '.webgl-libs')

/**
 * Locate headless-gl: the copy prepared by `scripts/bundle-webgl-libs.mjs`
 * (deployments), or the installed package (`next dev`). Resolved at runtime
 * so the bundler leaves it alone.
 */
function getGLDirectory() {
  const copy = path.join(LIBS_DIRECTORY, 'gl')
  if (existsSync(copy)) return copy
  return path.dirname(
    createRequire(path.join(process.cwd(), 'index.js')).resolve(
      'gl/package.json'
    )
  )
}

/**
 * On Linux, load the libraries ANGLE depends on by absolute path before the
 * first context is created: the bundled X11 client libraries (the function
 * runtime doesn't have them) and headless-gl's Vulkan loader. The dynamic
 * linker then reuses them when it resolves ANGLE's dependencies.
 */
function preloadLibraries(glDirectory: string): string[] {
  if (process.platform !== 'linux') return []

  const loadOrderFile = path.join(LIBS_DIRECTORY, 'load-order.json')
  const bundled: string[] = existsSync(loadOrderFile)
    ? JSON.parse(readFileSync(loadOrderFile, 'utf8'))
    : []
  const files = [
    ...bundled.map((name) => path.join(LIBS_DIRECTORY, name)),
    path.join(glDirectory, 'build', 'Release', 'libvulkan.so.1'),
  ]

  const loaded: string[] = []
  for (const file of files) {
    if (!existsSync(file)) continue
    try {
      ;(process as ProcessWithDlopen).dlopen(
        { exports: {} },
        file,
        RTLD_NOW | RTLD_GLOBAL | RTLD_NODELETE
      )
    } catch (error) {
      // Plain shared libraries aren't Node addons, so Node throws after
      // loading them. RTLD_NODELETE keeps them loaded anyway.
      if (!String(error).includes('did not self-register')) throw error
    }
    loaded.push(path.basename(file))
  }
  return loaded
}

let preloaded: string[] | undefined
let context: { gl: WebGL2RenderingContext; program: WebGLProgram } | undefined

function compileShader(
  gl: WebGL2RenderingContext,
  type: number,
  source: string
) {
  const shader = gl.createShader(type)!
  gl.shaderSource(shader, source)
  gl.compileShader(shader)
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    throw new Error(gl.getShaderInfoLog(shader) || 'Shader compilation failed.')
  }
  return shader
}

/**
 * Reuse one context and compiled program per function instance. Every card
 * has the same size, so the context never needs to be resized.
 */
function getContext(width: number, height: number) {
  if (context) {
    if (
      context.gl.drawingBufferWidth !== width ||
      context.gl.drawingBufferHeight !== height
    ) {
      throw new Error(`Expected a ${WIDTH}x${HEIGHT} canvas.`)
    }
    return context
  }

  const glDirectory = getGLDirectory()
  preloaded ??= preloadLibraries(glDirectory)
  const createGL: typeof import('gl') = createRequire(
    path.join(process.cwd(), 'index.js')
  )(glDirectory)
  const gl = createGL(width, height, {
    createWebGL2Context: true,
    useSwiftShader: true,
  })
  if (!gl) throw new Error('Failed to create a SwiftShader WebGL2 context.')

  const program = gl.createProgram()!
  gl.attachShader(program, compileShader(gl, gl.VERTEX_SHADER, VERTEX_SHADER))
  gl.attachShader(
    program,
    compileShader(gl, gl.FRAGMENT_SHADER, FRAGMENT_SHADER)
  )
  gl.bindAttribLocation(program, 0, 'position')
  gl.linkProgram(program)
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    throw new Error(gl.getProgramInfoLog(program) || 'Program linking failed.')
  }

  // A single triangle that covers the whole canvas.
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer())
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 3, -1, -1, 3]),
    gl.STATIC_DRAW
  )
  gl.enableVertexAttribArray(0)
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0)

  context = { gl, program }
  return context
}

// Renders share one context, so they must not interleave.
let queue: Promise<unknown> = Promise.resolve()
function exclusive<T>(task: () => Promise<T>): Promise<T> {
  const result = queue.then(task)
  queue = result.catch(() => undefined)
  return result
}

const fontData = readFile(
  path.join(process.cwd(), 'public', 'geist-700-normal.ttf')
)

function hashText(text: string) {
  let hash = 0
  for (let i = 0; i < text.length; i++) {
    hash = (hash * 31 + text.charCodeAt(i)) | 0
  }
  return (Math.abs(hash) % 1000) / 10
}

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const query = Array.isArray(req.query.text)
    ? req.query.text[0]
    : req.query.text
  const text = (query || 'Hello, WebGL').slice(0, MAX_TEXT_LENGTH)
  const timings: string[] = []

  async function time<T>(name: string, task: () => T | Promise<T>) {
    const start = performance.now()
    const result = await task()
    timings.push(`${name};dur=${(performance.now() - start).toFixed(1)}`)
    return result
  }

  const background: WebGLCanvasRenderer = (gl, { width, height }) => {
    const start = performance.now()
    const { program } = getContext(width, height)
    gl.useProgram(program)
    gl.uniform2f(gl.getUniformLocation(program, 'resolution'), width, height)
    gl.uniform1f(gl.getUniformLocation(program, 'seed'), hashText(text))
    gl.drawArrays(gl.TRIANGLES, 0, 3)
    gl.finish()
    timings.push(`shader;dur=${(performance.now() - start).toFixed(1)}`)
  }

  try {
    const fonts = [
      { name: 'Geist', data: await fontData, weight: 700 as const },
    ]
    const svg = await exclusive(() =>
      time('satori', () =>
        satori(
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              width: '100%',
              height: '100%',
              backgroundColor: 'black',
            }}
          >
            <canvas
              width={WIDTH}
              height={HEIGHT}
              webgl={background}
              style={{
                position: 'absolute',
                left: 0,
                top: 0,
                width: '100%',
                height: '100%',
              }}
            />
            <div
              style={{
                display: 'flex',
                maxWidth: 1000,
                padding: '32px 56px',
                borderRadius: 32,
                backgroundColor: 'rgba(0, 0, 0, 0.45)',
                color: 'white',
                fontFamily: 'Geist',
                fontSize: 72,
                fontWeight: 700,
                letterSpacing: -2,
                lineHeight: 1.1,
                textAlign: 'center',
              }}
            >
              {text}
            </div>
          </div>,
          {
            width: WIDTH,
            height: HEIGHT,
            fonts,
            createWebGLContext: (width: number, height: number) =>
              time('context', () => getContext(width, height).gl),
          }
        )
      )
    )
    const png = await time('resvg', () => new Resvg(svg).render().asPng())

    res.setHeader('Content-Type', 'image/png')
    res.setHeader('Cache-Control', 'no-store')
    res.setHeader('Server-Timing', timings.join(', '))
    res.send(png)
  } catch (error) {
    // Report enough to debug the native setup on a deployment.
    res.status(500).json({
      error: error instanceof Error ? error.stack : String(error),
      platform: `${process.platform}-${process.arch}`,
      node: process.version,
      preloaded,
    })
  }
}

import type { NextRequest } from 'next/server'
import { FontDetector, languageFontMap } from '../../utils/font'

export const config = {
  runtime: 'edge',
}

const detector = new FontDetector()

// Our own encoding of multiple fonts and their code, so we can fetch them in one request. The structure is:
// [1 byte = X, length of language code][X bytes of language code string][4 bytes = Y, length of font][Y bytes of font data]
// Note that:
// - The language code can't be longer than 255 characters.
// - The language code can't contain non-ASCII characters.
// - The font data can't be longer than 4GB.
// When there are multiple fonts, they are concatenated together.
function encodeFontInfoAsArrayBuffer(code: string, fontData: ArrayBuffer) {
  // 1 byte per char
  const buffer = new ArrayBuffer(1 + code.length + 4 + fontData.byteLength)
  const bufferView = new Uint8Array(buffer)
  // 1 byte for the length of the language code
  bufferView[0] = code.length
  // X bytes for the language code
  for (let i = 0; i < code.length; i++) {
    bufferView[i + 1] = code.charCodeAt(i)
  }

  // 4 bytes for the length of the font data
  new DataView(buffer).setUint32(1 + code.length, fontData.byteLength, false)

  // Y bytes for the font data
  bufferView.set(new Uint8Array(fontData), 1 + code.length + 4)

  return buffer
}

export default async function loadGoogleFont(req: NextRequest) {
  if (req.nextUrl.pathname !== '/api/font') return

  const { searchParams } = new URL(req.url)

  const fonts = searchParams.getAll('fonts')
  const text = searchParams.get('text')

  if (!fonts || fonts.length === 0 || !text) return

  const textByFont = await detector.detect(text, fonts)

  const _fonts = Object.keys(textByFont)

  const encodedFontBuffers: ArrayBuffer[] = []
  let fontBufferByteLength = 0
  ;(
    await Promise.all(_fonts.map((font) => fetchFont(textByFont[font], font)))
  ).forEach((fontData, i) => {
    if (fontData) {
      // TODO: We should be able to directly get the language code here :)
      const langCode = Object.entries(languageFontMap).find(
        ([, v]) => v === _fonts[i]
      )?.[0]

      if (langCode) {
        const buffer = encodeFontInfoAsArrayBuffer(langCode, fontData)
        encodedFontBuffers.push(buffer)
        fontBufferByteLength += buffer.byteLength
      }
    }
  })

  const responseBuffer = new ArrayBuffer(fontBufferByteLength)
  const responseBufferView = new Uint8Array(responseBuffer)
  let offset = 0
  encodedFontBuffers.forEach((buffer) => {
    responseBufferView.set(new Uint8Array(buffer), offset)
    offset += buffer.byteLength
  })

  return new Response(responseBuffer, {
    headers: {
      'Content-Type': 'font/woff',
      'Cache-Control': 'public, max-age=31536000, immutable',
    },
  })
}

async function fetchFont(
  text: string,
  font: string
): Promise<ArrayBuffer | null> {
  const API = `https://fonts.googleapis.com/css2?family=${font}&text=${encodeURIComponent(
    text
  )}`

  const css = await (
    await fetch(API, {
      headers: {
        // Make sure it returns TTF.
        'User-Agent':
          'Mozilla/5.0 (Macintosh; U; Intel Mac OS X 10_6_8; de-at) AppleWebKit/533.21.1 (KHTML, like Gecko) Version/5.0.5 Safari/533.21.1',
      },
    })
  ).text()

  const resource = css.match(/src: url\((.+)\) format\('(opentype|truetype)'\)/)

  if (!resource) return null

  const res = await fetch(resource[1])

  return res.arrayBuffer()
}

